signature.code:
useFieldArray(resource, path): {
  fields: { id, index, item }[],
  append, prepend, insert, remove, swap, move
}

examples.code:
function Addresses({ resource }) {
  const { fields, append, remove } = useFieldArray(resource, 'addresses');

  return (
    <>
      {fields.map((row) => (
        <fieldset key={row.id}>
          <City resource={resource} index={row.index} />
          <button type="button" onClick={() => remove(row.index)}>Remove</button>
        </fieldset>
      ))}
      <button
        type="button"
        onClick={() => append({ label: 'Warehouse', line1: '', city: '', state: '', postalCode: '', country: 'US' })}
      >
        Add address
      </button>
    </>
  );
}

function City({ resource, index }) {
  const { value, onChange, onBlur } = useField(resource, `addresses.${index}.city`);
  return <input value={value ?? ''} onChange={(e) => onChange(e.target.value)} onBlur={onBlur} />;
}

function Tags({ resource }) {
  const { fields, append, remove } = useFieldArray(resource, 'tags');
  const [text, setText] = useState('');

  return (
    <div>
      <ul>
        {fields.map((row) => (
          <li key={row.id}>
            {String(row.item)}
            <button type="button" onClick={() => remove(row.index)}>×</button>
          </li>
        ))}
      </ul>
      <input value={text} onChange={(e) => setText(e.target.value)} />
      <button
        type="button"
        onClick={() => {
          if (!text.trim()) return;
          append(text.trim());
          setText('');
        }}
      >
        Add
      </button>
    </div>
  );
}

function SortableLines({ resource }) {
  const { fields, move, swap } = useFieldArray(resource, 'lineItems');

  return fields.map((row) => (
    <div key={row.id}>
      <LineEditor resource={resource} index={row.index} />
      <button
        type="button"
        disabled={row.index === 0}
        onClick={() => move(row.index, row.index - 1)}
      >
        Up
      </button>
      <button
        type="button"
        disabled={row.index === fields.length - 1}
        onClick={() => move(row.index, row.index + 1)}
      >
        Down
      </button>
      {row.index > 0 && (
        <button type="button" onClick={() => swap(row.index, 0)}>
          Make first
        </button>
      )}
    </div>
  ));
}
